const browserPluginRoot = process.env.ZCODE_PLUGIN_ROOT ?? process.env.CLAUDE_PLUGIN_ROOT;
if (!browserPluginRoot) throw new Error('Browser plugin root is unavailable in the node_repl host');
const { join } = await import('node:path');
const { pathToFileURL } = await import('node:url');
const browserClientUrl = pathToFileURL(join(browserPluginRoot, 'scripts', 'browser-client.mjs')).href;
const { setupBrowserRuntime } = await import(browserClientUrl);
await setupBrowserRuntime({ globals: globalThis });
const browser = await agent.browsers.get('iab');
const expectedTabId = '{{latestBrowserTabId}}';
const tab = await browser.tabs.get(expectedTabId);
const animatedInput = tab.playwright.getByLabel('Animated Name');
const sharedCount = await animatedInput.count();
const fillStartedAt = Date.now();
await animatedInput.fill('ZCode');
const fillCompletedBefore25s = Date.now() - fillStartedAt < 25000;
let strictMessage = '';
try {
  await tab.playwright.getByRole('button', { name: 'Duplicate' }).click();
} catch (error) {
  strictMessage = error instanceof Error ? error.message : String(error);
}
let overlayMessage = '';
try {
  await tab.playwright.locator('#covered-button').click();
} catch (error) {
  overlayMessage = error instanceof Error ? error.message : String(error);
}
const leakedInternalError = /AbortError|Cannot read properties of undefined|undefined.*count/i.test(strictMessage + '\n' + overlayMessage);
const cuaInput = tab.playwright.getByLabel('CUA Name');
await cuaInput.click();
await new Promise((resolve) => setTimeout(resolve, 4000));
await tab.cua.type({ text: 'ZCode' });
await tab.playwright.getByRole('button', { name: 'Submit' }).click();
for (const width of [373, 374]) {
  await tab.setViewportSize({ width, height: 667 });
  await nodeRepl.emitImage(await tab.screenshot());
}
await tab.setViewportSize({ width: 375, height: 667 });
const status = await tab.playwright.getByRole('status').innerText();
const recoveredSameTab = tab.id === expectedTabId;
const allActionabilityChecksPassed = recoveredSameTab && sharedCount === 2 && fillCompletedBefore25s && strictMessage.length > 0 && overlayMessage.length > 0 && !leakedInternalError && status === 'Submitted ZCode / ZCode';
({
  marker: allActionabilityChecksPassed ? 'E2E_BROWSER_USE_IAB_ACTIONABILITY_OK' : 'E2E_BROWSER_USE_IAB_ACTIONABILITY_FAILED',
  recoveredSameTab,
  sharedCount,
  fillCompletedBefore25s,
  strictRejected: strictMessage.length > 0,
  overlayRejected: overlayMessage.length > 0,
  leakedInternalError,
  animatedInputValue: await animatedInput.getAttribute('value'),
  inputValue: await cuaInput.getAttribute('value'),
  status,
  viewport: tab.viewportSize(),
  tabs: await browser.tabs.list()
});
